import './App.css';
import {Select, Space, Table} from "antd";
import {getPointList, GetPointListURL} from "./api/point/point";
import useSWR from "swr";
import {useState} from "react";
import {DetailModal} from "./DetailModal";

const {Option} = Select;

const App = () => {
    const [searchText, setSearchText] = useState('');
    const [selectedPoint, setSelectedPoint] = useState(null);
    const {data: points, error} = useSWR(GetPointListURL, getPointList)

    const columns = [
        {
            title: '点名', dataIndex: 'name', key: 'name', render: (text, record) => {
                return <a style={{color: 'blue', cursor: 'pointer'}} onClick={() => setSelectedPoint(record)}>{text}</a>
            }
        },
        {title: '描述', dataIndex: 'description', key: 'description'},
        {title: '单位', dataIndex: 'unit', key: 'unit'},
        {title: '低报限值', dataIndex: 'lowAlarmLimit1Value', key: 'lowAlarmLimit1Value'},
        {title: '高报限值', dataIndex: 'highAlarmLimit1Value', key: 'highAlarmLimit1Value'},
        {title: '低低报限值', dataIndex: 'lowAlarmLimit2Value', key: 'lowAlarmLimit2Value'},
        {title: '高高报限值', dataIndex: 'highAlarmLimit2Value', key: 'highAlarmLimit2Value'},
    ];

    const filteredPoints = points?.filter(point => point.name.includes(searchText));

    const handleSearch = value => {
        setSearchText(value || '');
    };

    const handleModalClose = () => {
        setSelectedPoint(null);
    };

    return (
        <div className="App">
            <Space>
                <span>点名:</span>
                <Select
                    showSearch
                    style={{width: 400}}
                    placeholder="搜索点名"
                    optionFilterProp="children"
                    onChange={handleSearch}
                    allowClear
                    filterOption={(input, option) =>
                        option.children.toLowerCase().indexOf(input.toLowerCase()) >= 0
                    }
                >
                    {points?.map(point => (
                        <Option key={point.id} value={point.name}>{point.name}</Option>
                    ))}
                </Select>
            </Space>

            <Table className='w-full' size='small' dataSource={filteredPoints} columns={columns} rowKey='id'/>

            {/*详情模态框*/}
            {selectedPoint && <DetailModal selectedPoint={selectedPoint} onCancel={handleModalClose}/>}
        </div>
    );
};

export default App;