import API from "../api";
import {message} from "antd";

export const GetPointListURL = '/api/Home/GetPoints'
export const GetTablesByPoint = '/api/Home/GetTablesByPoint'
export const GetTableExist = '/api/Home/GetTableExist'
export const GetPointTablePage = '/api/Home/GetPointTablePage' // 获取表名数据
export const GetListByTimeRange = 'api/Home/GetListByTimeRange' // 根据时间段获取数据
export const GetFirstLastTS = 'api/Home/GetFirstLastTS' // 根据表名获取 第一个和最后一个时间戳
export const getPointList = () => {
    return API.get(GetPointListURL).then(res => {
        return Promise.resolve(res);
    }).catch(err => {
        return Promise.reject(err);
    });
}

export const getPointValByNames = (names) => {
    return API.request({
        url: GetPointListURL,
        method: 'post',
        data: names
    }).catch(err => message.error(err.response.data))
}
export const getTablesByPoint = (pointName) => {
    return API.request({
        url: GetTablesByPoint,
        method: 'get',
        params: {pointName}
    }).catch(err => message.error(err.response.data))
}

export const getTableExist = (tableName) => {
    return API.request({
        url: GetTableExist,
        method: 'get',
        params: {tableName}
    }).catch(err => message.error(err.response.data))
}

// 获取表名数据 (分页)
export const getPointTablePage = (params) => {
    return API.request({
        url: GetPointTablePage,
        method: 'get',
        params
    }).catch(err => message.error(err.response.data))
}
// 根据时间段获取数据
export const getListByTimeRange = (params) => {
    return API.request({
        url: GetListByTimeRange,
        method: 'get',
        params
    }).catch(err => message.error(err.response.data))
}
// 根据表名获取 第一个和最后一个时间戳
export const getFirstLastTS = (tableName) => {
    return API.request({
        url: GetFirstLastTS,
        method: 'get',
        params: {tableName}
    }).catch(err => message.error(err.response.data))
}