import {useState} from "react";
import useSWR from "swr";
import {getPointTablePage} from "./api/point/point";
import {Pagination, Table} from "antd";
import dayjs from "dayjs";

export const AlarmTable = ({name}) => {
    const [params, setParams] = useState({tableName: name, pageNo: 1, pageSize: 3})
    const {data} = useSWR([getPointTablePage, params], (params) => getPointTablePage(params[1]))

    const columns = [
        {
            title: '时间',
            dataIndex: 'ts',
            key: 'ts',
            render: (text) =>  dayjs(text).format('YYYY-MM-DD HH:mm:ss.SSS')
        },
        {
            title: '是否报警',
            dataIndex: 'isalarm',
            key: 'isalarm',
        },
        {
            title: '报警类型',
            dataIndex: 'alarmtype',
            key: 'alarmtype',
        },
    ];
    const handlePageChange = (page, pageSize) => {
        setParams({...params, pageNo: page, pageSize})
    };
    return data && <>
        <Table scroll={{y: 440}} columns={columns} dataSource={data.list} pagination={false}/>
        <Pagination showSizeChanger  current={params.pageNo} pageSize={params.pageSize} total={data.total} onChange={handlePageChange} rowKey='ts'/>
    </>;
};