import {Modal, Tabs} from "antd";
import {LatestValue} from "./LatestValue";
import {PointTable} from "./PointTable";
import {AlarmTable} from "./AlarmTable";
import {PointChart} from "./PointChart";
import {useState} from "react";


export const DetailModal = ({onCancel, selectedPoint}) => {

    const name = selectedPoint.name.toLowerCase();

    let items = [
        {
            key: '1',
            label: '最新值',
            children: <LatestValue name={selectedPoint.name}/>,
        },
        {

            key: name,
            label: '点数据表',
            children: <PointTable name={name}/>,
        },
        {
            key: `${name}_alarm`,
            label: '报警数据表',
            children: <AlarmTable name={`${name}_alarm`}/>,
        }
        ,
        {
            key: '2',
            label: '点数据统计表',
            children: <PointChart name={name}/>,
        },
    ];
    const onChange = (key) => {
    };

    return <Modal
        width='60%'
        title={selectedPoint?.name}
        open={!!selectedPoint}
        onCancel={onCancel}
        footer={null}
    >
        <Tabs defaultActiveKey="1" items={items} onChange={onChange}/>
    </Modal>;
};