import {useState} from "react";
import dayjs from "dayjs";
import {getFirstLastTS, getListByTimeRange} from "./api/point/point";
import ReactECharts from 'echarts-for-react';
import {useDebounceFn, useMount} from "ahooks";

const getLineChart = (originData, interval, start = 0, end = 100) => {
    originData = originData.map(x => {
        const alarm = Math.random() >= 0.8;
        const val = {
            ...x,
            isAlarm: alarm,
            alarmType: alarm ? '低报' : '无',
        }
        return val;
    })
    let format = 'YYYY-MM-DD HH:mm:ss.SSS'
    if (interval.includes('n')) {
        format = 'YYYY-MM'
    } else if (interval.includes('d')) {
        format = 'YYYY-MM-DD'
    } else if (interval.includes('h')) {
        format = 'YYYY-MM-DD HH'
    } else if (interval.includes('m')) {
        format = 'HH:mm'
    } else if (interval.includes('s')) {
        format = 'HH:mm:ss'
    } else if (interval.includes('a')) {
        format = 'HH:mm:ss.SSS'
    }
    const data = originData.reduce((acc, cur, index) => {
        if (cur.isAlarm) {
            acc.push({
                xAxis: index,

            })
        }
        return acc
    }, []);
    return ({
        animation: false, // 禁用动画效果
        grid: {top: 8, right: 8, bottom: 50, left: 36},
        xAxis: {
            type: 'category',
            data: originData.map(x => dayjs(x.ts).format(format)),

        },
        yAxis: {
            type: 'value',

        },
        series: [
            {
                data: originData.map(x => x.value),
                type: 'line',
                smooth: true,
                markLine: {
                    symbol: ['none', 'none'],
                    label: {show: false},
                    data: data,
                    lineStyle: {
                        color: 'red',
                    }
                },
            },
        ],
        tooltip: {
            trigger: 'axis',
            axisPointer: {
                type: 'cross',
                label: {
                    backgroundColor: '#6a7985',
                },
            },
            formatter: (params) => {
                // console.log('params ', params)
                const axisValue = params[0].axisValue;
                const find = originData.find(x => dayjs(x.ts).format(format) === axisValue);
                // console.log('find', find)
                return `时间:${axisValue}<br />
                数值: ${params[0].data}<br />
                是否报警: ${find?.isAlarm}<br />
                报警类型: ${find?.alarmType}
                `;
            },
        },
        dataZoom: [
            {
                type: 'inside',
                start,
                end,
            },
            {
                show: true,
                type: 'slider',
                start: start,
                end: end,
                bottom: 0,
                height: 30,
                handleSize: 20,
                handleStyle: {
                    color: '#ddd',
                },
                backgroundColor: '#f7f7f7',
                borderColor: '#ddd',
                fillerColor: '#ddd',
                labelFormatter: '',
            }
        ],
    });
};
const getInterval = (startTime, endTime) => {
    // get  startTime endTime diff ,
    // if diff > 1 year, then set interval to 1 month
    // if diff > 1 month, then set interval to 1 day
    // if diff > 1 day, then set interval to 1 hour
    // if diff > 1 hour, then set interval to 1 minute
    // if diff > 1 minute, then set interval to 1 second
    const diff = dayjs(endTime).diff(dayjs(startTime), 'second')
    let interval = '10a'
    if (diff > 60 * 60 * 24 * 365) {
        interval = '1n' // 1 月
    } else if (diff > 60 * 60 * 24 * 30) {
        interval = '1d' // 1 天
    } else if (diff > 60 * 60 * 24) {
        interval = '1h' // 1 小时
    } else if (diff > 60 * 60) {
        interval = '3s' // 1 分钟
    } else if (diff > 60) {
        interval = '1s' // 1 秒
    }
    return interval
}


export const PointChart = ({name}) => {
    const [originData, setOriginData] = useState([])
    const [options, setOptions] = useState({})
    // 先获取一下原始数据
    useMount(async () => {
        let startTs = 0;
        let endTs = 0;
        let res = await getFirstLastTS(name)
        if (res.length === 0) {
            console.log('无数据')
            return
        }
        if (res.length === 1) {
            startTs = res[0] - 1;
            endTs = res[0] + 1;
        } else {
            startTs = res[0];
            endTs = res[1];
        }

        const startTime = dayjs(startTs).format('YYYY-MM-DD HH:mm:ss.SSS')
        const endTime = dayjs(endTs).format('YYYY-MM-DD HH:mm:ss.SSS')
        const interval = getInterval(startTime, endTime)
        console.log('mount interval', interval)
        const params = {tableName: name, startTime, endTime, interval}
        res = await getListByTimeRange(params)
        setOriginData(res);
        setOptions(getLineChart(res, interval))
    })


    const handleChartZoom = (e) => {
        console.log('e', e)
        if (!e) return
        let start, end = 0;
        if (e.batch) {
            start = e.batch[0].start * 0.01;
            end = e.batch[0].end * 0.01;
        } else {
            start = e.start * 0.01;
            end = e.end * 0.01;
        }
        if (originData.length === 0) {
            console.log('无数据, 无法缩放');
            return;
        }
        const arr = originData.map(x => x.ts)
        const result = arr.reduce((acc, cur, index) => {
            const startDiff = Math.abs(start - (index / arr.length));
            const endDiff = Math.abs(end - (index / arr.length));
            if (startDiff < acc.startDiff) {
                acc.startDiff = startDiff;
                acc.startIndex = index;
            }
            if (endDiff < acc.endDiff) {
                acc.endDiff = endDiff;
                acc.endIndex = index;
            }
            return acc;
        }, {startDiff: Infinity, endDiff: Infinity});

        const startIndex = result.startIndex;
        const startTime = dayjs(arr[startIndex]).format('YYYY-MM-DD HH:mm:ss.SSS');
        const endIndex = result.endIndex;
        const endTime = dayjs(arr[endIndex]).format('YYYY-MM-DD HH:mm:ss.SSS');
        console.log('startTime', startTime, 'endTime', endTime)

        const interval = getInterval(startTime, endTime)
        console.log('interval', interval)
        // get data by startTime endTime interval ,and insert between startIndex endIndex
        getListByTimeRange({tableName: name, startTime, endTime, interval}).then(res => {
            const newData = [...originData]
            newData.splice(startIndex, endIndex - startIndex, ...res)
            console.log('newData.length', newData.length)
            setOriginData(newData)
            setOptions(getLineChart(newData, interval, start * 100, end * 100))
        })
    };
    const {run: debouncedHandleChartZoom} = useDebounceFn(handleChartZoom, {wait: 400});


    return <ReactECharts option={options} onEvents={{
        'datazoom': debouncedHandleChartZoom,
    }}/>;
};