import useSWR from "swr";
import {GetPointTablePage, getPointTablePage} from "./api/point/point";
import {useState} from "react";
import {Pagination, Table} from "antd";
import dayjs from "dayjs";

export const PointTable = ({name}) => {
    const [params, setParams] = useState({tableName: name, pageNo: 1, pageSize: 20})
    const {data} = useSWR([GetPointTablePage, params], (params) => getPointTablePage(params[1]))

    const columns = [
        {
            title: '时间',
            dataIndex: 'ts',
            key: 'ts',
            render: (text) =>  dayjs(text).format('YYYY-MM-DD HH:mm:ss.SSS')
        },
        {
            title: '值',
            dataIndex: 'pvalue',
            key: 'pvalue',
        },
    ];
    const handlePageChange = (page, pageSize) => {
        setParams({...params, pageNo: page, pageSize})
    };
    return data && <>
        <Table scroll={{y: 440}} columns={columns} dataSource={data.list} pagination={false}/>
        <Pagination showSizeChanger rowKey='ts' current={params.pageNo} pageSize={params.pageSize} total={data.total}
                    onChange={handlePageChange}/>
    </>;
};
